vector<Record> LoadScoreHistory() {
    vector<Record> records;
    std::ifstream inFile("GameScore.txt");
    if (inFile.is_open()) {
        string result; int score, time;
        while (inFile >> result >> score >> time) {
            records.push_back({result, score, time});
        }
        inFile.close();
    }
    return records;
}
```
