vector<CellData> ParseMapCell(const QString& mapFilePath) {
    vector<CellData> cells;
    QFile file(mapFilePath);
    if (!file.open(QIODevice::ReadOnly | QIODevice::Text)) return cells;
    QByteArray data = file.readAll();
    QJsonParseError error;
    QJsonDocument doc = QJsonDocument::fromJson(data, &error);
    if (error.error != QJsonParseError::NoError) {
        qWarning() << "JSON parse error:" << error.errorString();
        return cells;
    }
    QJsonObject root = doc.object();
    for (const QString& key : root.keys()) {
        if (key.contains("Cell")) {
            QJsonObject obj = root[key].toObject();
            CellData cell;
            cell.num = obj["Num"].toInt();
            cell.type = obj["Type"].toInt();
            cell.height = obj["Height"].toInt();
            cells.push_back(cell);
        }
    }
    file.close();
    return cells;
}
```
注意——`toInt()`做类型转换，QJsonParseError检查解析是否成功。请完成。"
